  var IS_H5 = location.pathname.indexOf('/h5/') >= 0;
  var IS_OPP_PC = PAGE === 'pc-opp-list' || PAGE === 'pc-opp-create' || PAGE === 'pc-opp-detail';
  var IS_CUSTOMER_PC = PAGE.indexOf('pc-customer-') === 0;
  var IS_CONTACT_PC = PAGE.indexOf('pc-contact-') === 0;
  var MK = (PAGE === 'pc-lead-list' || PAGE === 'pc-lead-detail' || PAGE === 'pc-lead-convert') ? 'ry-lead-notes-mode' : (IS_OPP_PC ? 'ry-opp-notes-mode' : (IS_CUSTOMER_PC ? 'ry-customer-notes-mode' : (IS_CONTACT_PC ? 'ry-contact-notes-mode' : 'ry-notes-mode'))), TK = 'ry-notes-todo-only', CK = 'ry-notes-card-open';
  var defaultCardOpen = PAGE.indexOf('pc-opp-') === 0 ? '0' : (IS_H5 ? '0' : '1');
  var IS_LEAD_PC = PAGE === 'pc-lead-list' || PAGE === 'pc-lead-detail' || PAGE === 'pc-lead-convert';
  var IS_FOCUSED_PC = IS_LEAD_PC || IS_OPP_PC || IS_CUSTOMER_PC || IS_CONTACT_PC;
  var state = { mode: rd(MK, IS_FOCUSED_PC ? 'full' : 'mark'), todoOnly: rd(TK, '') === '1', cardOpen: rd(CK, defaultCardOpen) === '1' };
